#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<string> S(5);
    for (auto& s : S) cin >> s;
    int ans = 5;
    auto check = [&](int x0, int y0, int dx, int dy) {
        int count = 0;
        for (int i = 0; i < 5; i++)
            if (S[x0 + dx * i][y0 + dy * i] == '.') count++;
        ans = min(ans, count);
    };
    for (int k = 0; k < 5; k++) check(k, 0, 0, 1);
    for (int k = 0; k < 5; k++) check(0, k, 1, 0);
    check(0, 0, 1, 1);
    check(0, 4, 1, -1);
    cout << ans << "\n";
}
